def lengthOfLIS(nums):
    sub = []
    for num in nums:
        # Find the index in the subsequence where num should be inserted
        i = binarySearch(sub, num)
        # If num is greater than any element in sub
        if i == len(sub):
            sub.append(num)
        # Replace the element in sub
        else:
            sub[i] = num
    return len(sub)

def binarySearch(sub, num):
    left, right = 0, len(sub) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if sub[mid] < num:
            left = mid + 1
        else:
            right = mid - 1
    return left

