def combinationSum4(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1  # There is one way to reach a target of 0, which is to choose nothing

    for total in range(1, target + 1):
        for num in nums:
            if total - num >= 0:
                dp[total] += dp[total - num]

    return dp[target]

