def rob(nums):
    def rob_linear(houses):
        if not houses:
            return 0
        if len(houses) <= 2:
            return max(houses)

        dp = [0] * len(houses)
        dp[0], dp[1] = houses[0], max(houses[0], houses[1])

        for i in range(2, len(houses)):
            dp[i] = max(dp[i - 1], dp[i - 2] + houses[i])

        return dp[-1]

    if len(nums) == 1:
        return nums[0]

    return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

