def cloneGraph(node):
    if not node:
        return None

    # Dictionary to save the cloned node reference
    cloned_nodes = {}

    def dfs(node):
        if node in cloned_nodes:
            return cloned_nodes[node]

        copy = Node(node.val)
        cloned_nodes[node] = copy

        for neighbor in node.neighbors:
            copy.neighbors.append(dfs(neighbor))

        return copy

    return dfs(node)

