def canFinish(numCourses, prerequisites):
    def dfs(course):
        if course in visited:
            return False
        if course in checked:
            return True

        visited.add(course)
        for prereq in graph[course]:
            if not dfs(prereq):
                return False
        visited.remove(course)
        checked.add(course)

        return True

    # Create a graph from prerequisites
    graph = {i: [] for i in range(numCourses)}
    for course, prereq in prerequisites:
        graph[course].append(prereq)

    visited = set()  # Tracks courses during a DFS
    checked = set()  # Tracks courses that have been confirmed to be acyclic

    for course in range(numCourses):
        if not dfs(course):
            return False

    return True

