from collections import defaultdict, deque

def alienOrder(words):
    # Create a graph (adjacency list) and a set of all unique letters
    graph = defaultdict(set)
    letters = set(''.join(words))
    in_degree = {char: 0 for char in letters}

    # Build the graph and count in-degrees
    for i in range(len(words) - 1):
        min_length = min(len(words[i]), len(words[i + 1]))
        for j in range(min_length):
            if words[i][j] != words[i + 1][j]:
                if words[i + 1][j] not in graph[words[i][j]]:
                    graph[words[i][j]].add(words[i + 1][j])
                    in_degree[words[i + 1][j]] += 1
                break
        else:  # Check if second word is a prefix of first word
            if len(words[i]) > len(words[i + 1]):
                return ""

    # Topological sort using BFS (Kahn's algorithm)
    queue = deque([char for char in in_degree if in_degree[char] == 0])
    alien_order = ""

    while queue:
        char = queue.popleft()
        alien_order += char
        for next_char in graph[char]:
            in_degree[next_char] -= 1
            if in_degree[next_char] == 0:
                queue.append(next_char)

    if len(alien_order) < len(letters):
        return ""  # Cycle detected or not all letters are connected

    return alien_order

