class UnionFind:
    def __init__(self, size):
        self.root = [i for i in range(size)]

    def find(self, x):
        if x == self.root[x]:
            return x
        self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            self.root[rootY] = rootX
            return True
        return False

def validTree(n, edges):
    if len(edges) != n - 1:  # Check for correct number of edges
        return False

    uf = UnionFind(n)
    for a, b in edges:
        if not uf.union(a, b):  # If a union returns False, a cycle is found
            return False

    return True

