def reverseListIterative(head):
    prev, curr = None, head
    while curr:
        next_temp = curr.next
        curr.next = prev
        prev = curr
        curr = next_temp
    return prev

def reverseListRecursive(head):
    if not head or not head.next:
        return head
    reversed_head = reverseListRecursive(head.next)
    head.next.next = head
    head.next = None
    return reversed_head

