def mergeKLists(lists):
    min_heap = []
    for head in lists:
        while head:
            heapq.heappush(min_heap, head.val)
            head = head.next

    dummy = ListNode()
    current = dummy
    while min_heap:
        smallest_val = heapq.heappop(min_heap)
        current.next = ListNode(smallest_val)
        current = current.next

    return dummy.next

