def isValidBST(root, lower=float('-inf'), upper=float('inf')):
    if not root:
        return True

    val = root.val
    if val <= lower or val >= upper:
        return False

    if not isValidBST(root.right, val, upper):
        return False

    if not isValidBST(root.left, lower, val):
        return False

    return True

