class TrieNode:
    def __init__(self):
        self.children = {}
        self.isEndOfWord = False
        self.word = None

def buildTrie(words):
    root = TrieNode()
    for word in words:
        node = root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.isEndOfWord = True
        node.word = word
    return root

def findWords(board, words):
    root = buildTrie(words)
    rows, cols = len(board), len(board[0])
    result = set()

    def dfs(r, c, node):
        char = board[r][c]
        if char not in node.children:
            return
        next_node = node.children[char]
        if next_node.isEndOfWord:
            result.add(next_node.word)

        board[r][c] = '#'  # Mark as visited
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                dfs(nr, nc, next_node)
        board[r][c] = char  # Backtrack

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)

    return list(result)

# Example usage
board = [["o","a","a","n"],["e","t","a","e"],["i","h","k","r"],["i","f","l","v"]]
words = ["oath","pea","eat","rain"]
print(findWords(board, words))  # Output: ['eat', 'oath']

import heapq

class MedianFinder:

    def __init__(self):
        # Max heap to store the lower half of elements (negative values)
        self.lower_half = []
        # Min heap to store the upper half of elements
        self.upper_half = []

    def addNum(self, num: int) -> None:
        # Add the number to the appropriate heap
        if not self.lower_half or num <= -self.lower_half[0]:
            heapq.heappush(self.lower_half, -num)
        else:
            heapq.heappush(self.upper_half, num)

        # Balance the heaps to ensure their sizes differ by at most 1
        if len(self.lower_half) > len(self.upper_half) + 1:
            heapq.heappush(self.upper_half, -heapq.heappop(self.lower_half))
        elif len(self.upper_half) > len(self.lower_half):
            heapq.heappush(self.lower_half, -heapq.heappop(self.upper_half))

    def findMedian(self) -> float:
        # Check if the total number of elements is even
        if len(self.lower_half) == len(self.upper_half):
            return (-self.lower_half[0] + self.upper_half[0]) / 2.0
        else:
            return -self.lower_half[0]

# Example usage:
medianFinder = MedianFinder()
medianFinder.addNum(1)
medianFinder.addNum(2)
print(medianFinder.findMedian())  # Output: 1.5
medianFinder.addNum(3)
print(medianFinder.findMedian())  # Output: 2.0
